func (e *StatefulEvaluator) runActions(
	ctx context.Context,
	ruleDef Definition,
	ec *ExecutionContext,
	actions []Action,
	entity *gtypes.EntityState,
	stateFields expression.StateFields,
	messageFields expression.MessageFields,
	entityID, relatedID string,
) {
	for _, action := range actions {
		if len(action.When) > 0 {
			match, whenErr := e.evaluateWhen(ctx, action.When, entity, stateFields, messageFields)
			if whenErr != nil {
				e.logger.Warn("When clause evaluation failed, skipping action",
					"rule_id", ruleDef.ID,
					"entity_id", entityID,
					"action_type", action.Type,
					"error", whenErr)
				continue
			}
			if !match {
				e.logger.Debug("Action skipped by When clause",
					"rule_id", ruleDef.ID,
					"entity_id", entityID,
					"action_type", action.Type)
				continue
			}
		}

		// Per-action firing-cap gate. Look up the action's stable
		// identifier (author-supplied Action.ID or deterministic hash),
		// compare against the resolved cap (effective default 3 when
		// unset; 0 = unlimited per operator opt-out), and skip the
		// action when it has already fired up to its cap. Counter
		// state lives on ec.State.ActionIterations and is persisted
		// to the StateTracker after runActions returns.
		if ec.State != nil {
			actionID := action.effectiveID(ruleDef.ID)
			maxIter, fromDefault := action.effectiveMaxIterations()
			fired := ec.State.ActionIterations[actionID]
			if !isUnlimited(maxIter) && fired >= maxIter {
				e.logger.Warn("Action firing cap reached, skipping",
					"rule_id", ruleDef.ID,
					"entity_id", entityID,
					"action_type", action.Type,
					"action_id", actionID,
					"fired", fired,
					"cap", maxIter,
					"cap_source", capSource(fromDefault))
				continue
			}
			if ec.State.ActionIterations == nil {
				ec.State.ActionIterations = map[string]int{}
			}
			ec.State.ActionIterations[actionID] = fired + 1
		}

		if err := e.actionExecutor.Execute(ctx, action, ec); err != nil {
			if errors.Is(err, ErrDenyVerdict) {
				// Deny is terminal: subsequent actions in this evaluation cycle do not
				// run. Non-deny errors continue best-effort dispatch (see else branch).
				e.logger.Info("rule action denied; short-circuiting remaining actions",
					"rule_id", ruleDef.ID,
					"entity_id", entityID,
					"action_type", action.Type,
					"error", err)
				break
			}
			e.logger.Error("Failed to execute action",
				"rule_id", ruleDef.ID,
				"entity_id", entityID,
				"related_id", relatedID,
				"action_type", action.Type,
				"error", err)
			// Every non-deny action-execution failure is otherwise only a
			// log line — a fail-closed action (e.g. publish_agent rejecting
			// a non-integer loop_max_iterations) is exactly the silent-
			// failure class this repo hunts if nothing alerts on it.
			if e.metrics != nil {
				e.metrics.actionFailuresTotal.WithLabelValues(action.Type).Inc()
			}
		}
	}
}

